// Lee el correo de Nequi Negocios y saca SOLO lo que QControla necesita.
// Todo lo demás (lead GANADO, venta, Purchase a Meta, documentos por correo)
// lo hace el backend en POST /api/pagos/nequi/confirmar.
//
// Etiquetas del correo (el pago llega por el link de Wompi):
//   Estado: APROBADA | RECHAZADA · Monto: COP $25,000 · Referencia1: <documento del cliente>
//   Referencia: <código Nequi> · Fecha: dd/mm/aaaa hh:mm
const correo = $input.item.json;
const texto = String(correo.text || correo.html || '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;| /g, ' ')
  .replace(/[ \t]+/g, ' ');

const campo = (re) => (texto.match(re)?.[1] || '').trim();

// Estado de la transacción. Nequi manda el MISMO correo (con monto y Referencia1)
// también cuando la transacción se RECHAZA: solo APROBADA es un pago.
// Se lee del cuerpo ("Estado: APROBADA") y, si no viene, del asunto
// ("Transacción APROBADA en …").
const estado = (
  campo(/Estado\s*:\s*([A-Za-zÁÉÍÓÚáéíóú]+)/) ||
  (/\b(APROBADA|RECHAZADA|DECLINADA|PENDIENTE|ANULADA)\b/i.exec(String(correo.subject || ''))?.[1] || '')
).toUpperCase();

// "25,000" · "25.000" · "25.000,00" · "25,000.00" → 25000
// Solo un separador seguido de exactamente 2 dígitos al final es decimal; los demás son de miles.
const leerMonto = (txt) => {
  if (!txt) return 0;
  const n = Number(txt.replace(/[.,](\d{2})$/, '#$1').replace(/[.,]/g, '').replace('#', '.'));
  return Number.isFinite(n) ? n : 0;
};

const monto = leerMonto(
  campo(/Monto\s*:\s*(?:COP)?\s*\$?\s*([\d.,]+)/i) || campo(/\$\s*([\d.,]+)/)
);

// Documento del cliente: lo escribe en "Referencia1" al pagar.
const documento = campo(/Referencia\s*1\s*:\s*([0-9A-Za-z][0-9A-Za-z.\-]{3,24})/i).replace(/[^0-9A-Za-z]/g, '');

// Código de la transacción en Nequi (para conciliar en la app de Nequi).
const referenciaNequi = campo(/Referencia\s*:\s*([0-9A-Za-z_.\-]+)/i);

// Número de transacción de Wompi: con él QControla consulta el pago en Wompi
// (estado real y el correo/celular que el cliente escribió al pagar).
const transaccion = campo(/N[uú]mero de transacci[oó]n\s*:\s*([0-9A-Za-z\-]+)/i);

return {
  json: {
    // Un correo = un pago: el id del correo de Gmail es la llave que evita
    // registrar dos veces la misma venta (no depende del formato de Nequi).
    referencia: correo.id,
    referencia_nequi: referenciaNequi || null,
    transaccion: transaccion || null,
    documento,
    monto,
    estado,
    fecha: correo.date || null,
    fecha_nequi: campo(/Fecha\s*:\s*([\d\/]+ [\d:]+)/i) || null,
    esValido: Boolean(estado === 'APROBADA' && documento && monto > 0),
  },
};

